\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Orationes ante missam}}\plain \f1\lang1033\fs24 . (15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Ps.-Anselmus Cantuariensis}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Oratio 32}}\plain \f1\lang1033\fs24 ]. \u8250 \'9b\plain \f1\i\lang1033\fs24 Brevis et optima oratio sacerdotis volentis celebrare\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Conscientia culpabilis vite trepidus et anxius criminum funibus captivatus te}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 deprecor\plain \f1\lang1033\fs24  \u8230 \'85 Druck: PL 158, Sp. 926 (in der Hs am Schlu\u223 \'df verk\u252 \'fcrzt); vgl. Glorieux, Pour revaloriser Migne, S. 62. (16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sequitur oratio ad beatam virginem ante missam\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Eya benignissima virgo et mater, mater Maria, spes et firmum refugium miserorum\plain \f1\lang1033\fs24  \u8230 \'85; (17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 18\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oratio bona ante missam dicenda\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Suscipe, clementissime pater, has obla(17v)tiones, quas ego peccator presumo offere}}\plain \f1\lang1033\fs24  \u8230 \'85 Auch {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hs Mainz, StB, Hs I 123}}\plain \f1\lang1033\fs24 , 94\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24 , Kat. Mainz 1, S. 219. (18\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Alia oratio\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Ante conspectum divine maiestatis tue, domine deus omnipotens, reus conscientie tristis assisto, rogare non audeo\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 veniam largiaris. Qui vivis.\plain \f1\lang1033\fs24  Druck: PL 78, Sp. 247f. (leicht ver\u228 \'e4nderte Variante der Apologie \u8222 \'84Ante oculos tuos\ldblquote ). (18\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Alia\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Domine Ihesu Christe, ante conspectum divine maiestatis tue reus assisto et non sum dignus videre altitudinem celi\plain \f1\lang1033\fs24  \u8230 \'85 (19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Schlie\u223 \'dft mit Versikel und \u8250 \'9b\plain \f1\i\lang1033\fs24 Collecta\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CO}}\plain \f1\lang1033\fs24  Nr 1828.}

