\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Orationes post communionem}}\plain \f1\lang1033\fs24 . (19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Post communionem lege sequentia\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Corpus et sanguis domini nostri Ihesu Christi custodiat animam meam}}\plain \f1\lang1033\fs24  \u8230 \'85; \u8250 \'9b\plain \f1\i\lang1033\fs24 Oratio\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Gratias ago tibi, omnipotens et misericors deus meus, gratiarum actiones tremende tue mai\plain \f1\lang1033\fs24 [e]\plain \f1\i\lang1033\fs24 stati\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 ubi tua sancta introierunt sacramenta. Amen.\plain \f1\lang1033\fs24  (20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Alia\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Laudo et benedico et tibi gratias ago, dulcissime Ihesu, quia me}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 laudare et glorificare. Amen.\plain \f1\lang1033\fs24  (21\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930gi/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Antiphona}}\plain \f1\lang1033\fs24 \u8249 \'8b. Magnificat-Antiphon der 1. Vesper an Fronleichnam. (21\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930gi/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Collecta}}\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CO}}\plain \f1\lang1033\fs24  Nr 4166 (Variante). 2862. Kombination aus 2841+4889. 4788. Diese Zusammenstellung auch Hs {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Frankfurt, StuUB, Ms. lat. oct. 110}}\plain \f1\lang1033\fs24 , 127\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 132\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Kat. Frankfurt 4.3, S. 116.}

