\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 99\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 103\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gebete f\u252 \'fcr ein gutes geistliches Leben}}\plain \f1\lang1033\fs24 . (99\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 100\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Oracio pro beneplacito dei perficiendo semper\u8249 \'8b. Concede michi, benignissime Ihesu Christe, graciam tuam, ut mecum sit}}\plain \f1\lang1033\fs24  \u8230 \'85 Auch {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hs Uppsala, UB, C 492}}\plain \f1\lang1033\fs24 , 7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Kat. Uppsala 5, S. 223. (100\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 103\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio pro augmento spiritualis vite et discipline. Pater noster. Ave Maria\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Per benignissimum respectum tue mise\plain \f1\lang1033\fs24 (101\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24 ricordie, amantissime Ihesu, quo respexisti\plain \f1\lang1033\fs24  \u8230 \'85 Es folgen 2 Gebete, Initien im Register.}

