\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 103\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gebete bei Traurigkeit und in Bedr\u228 \'e4ngnis}}\plain \f1\lang1033\fs24 . (103\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 105\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cum tristaris, ad solum deum habeas refugium\u8249 \'8b. Sit nomen tuum, domine, benedictum in secula, qui voluisti hanc tentacionem}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 venire super me\plain \f1\lang1033\fs24  \u8230 \'85; (105\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 106\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Item in tribulacionibus et persecucionibus accede ad imaginem crucifixi et dic flexis genibus\u8249 \'8b Salve crux veneranda, tu preciosior auro}}\plain \f1\lang1033\fs24  \u8230 \'85 Schlie\u223 \'dft mit Versikeln und Kollekte: (106\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CO}}\plain \f1\lang1033\fs24  Nr 1027.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (106\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 110\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Item cum tristaris, ora et dic\u8249 \'8b Ihesu pie, ea fiducia, qua umquam aliquis (106v) anxiatus vel turbatus ad te in sua confugit miseria}}\plain \f1\lang1033\fs24  \u8230 \'85 \u8250 \'9b\plain \f1\i\lang1033\fs24 Osculare vulnera pedum et dic\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Hic omnes causas mei meroris depono\plain \f1\lang1033\fs24  \u8230 \'85 3 Abschnitte, zusammengestellt aus Gebetsmeinung, Responsorium mit Versikel bzw. Antiphon, Hymnus: (107\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH}}\plain \f1\lang1033\fs24  51, Nr 89, (107\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 )  {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH}}\plain \f1\lang1033\fs24 50, Nr 144 (jeweils nur Anfang), (108\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) AH 51, Nr 72, und Gebet, Initien im Register. Schlie\u223 \'dft mit Kollekte: (110\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) CO Nr 3852.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (110\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cum homo in aliquo gravatur, ad pedes dei se prosternat ibique onus suum deo committendo deponat legatque oraciones sequentes\u8249 \'8b. Respice, domine sancte pater}}\plain \f1\i\lang1033\fs24 , super me famulam tuam, pro qua dominus noster Ihesus\plain \f1\lang1033\fs24  (110\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Christus non dubi}}\plain \f1\i\lang1033\fs24 tavit\plain \f1\lang1033\fs24  \u8230 \'85 Variante zu CO Nr 5104; vgl. {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hs Ebstorf, KlosterB, IV 5}}\plain \f1\lang1033\fs24 , 261\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , Kat. Niedersachsen 10, S. 34. Es folgen 3 kurze Gebete, Initien im Register, sowie (111\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) 2 Verse aus dem \u8222 \'84Exsultet\ldblquote  und Antiphon: \plain \f1\i\lang1033\fs24 O admirabile precium\plain \f1\lang1033\fs24  \u8230 \'85 Wie 108\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ; auch Graduale von Saint-Yrieix: s. Pal\u233 \'e9ographie musicale, Bd 13, 1925, Taf. 140, bzw. Antiphonar von Worcester: s. Pal\u233 \'e9ographie Musicale, Bd 12, 1922, Taf. 215f. Angeh\u228 \'e4ngt: (112\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Cum homo deum laudare sive amare cupit\plain \f1\lang1033\fs24  \u8230 \'85\u8249 \'8b. \plain \f1\i\lang1033\fs24 Ihesu bone, laudo te\plain \f1\lang1033\fs24  \u8230 \'85; \u8250 \'9b\plain \f1\i\lang1033\fs24 Cum vero amare delectat te, dic\plain \f1\lang1033\fs24 \u8249 \'8b. (112\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ihesu bone, amo te\plain \f1\lang1033\fs24  \u8230 \'85 Es folgen kurze Gebete zu den 3 g\u246 \'f6ttlichen Personen.}

