\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 129\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 133\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Meditationes de vita et de passione Christi}}\plain \f1\lang1033\fs24 . (129\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 131\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Meditaciones de passione domini nostri Ihesu Christi per diem circa horas in mente cogitandos\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 et primo ante matutinas\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Anxie oravit ad patrem, suda(130r)vit aquam et sanguinem}}\plain \f1\lang1033\fs24  \u8230 \'85 Stichwortartige Betrachtungen des Leidensweges Christi f\u252 \'fcr die 7 Horen. (131\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 133\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Articuli de vita Ihesu per ferias ruminandi pro devocione sequuntur.\plain \f1\lang1033\fs24  (131\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Feria secunda per diem\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Ex deo genitus. Prefiguratus. Emissus celitus. Marie natus.\plain \f1\lang1033\fs24  \u8250 \'9b\plain \f1\i\lang1033\fs24 Infra missam feria 2\plain \f1\i\super\lang1033\fs24 a\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Dolo venundatus. Orans prostratus.\plain \f1\lang1033\fs24  \u8230 \'85 F\u252 \'fcr Samstag und Sonntag die Anzahl der \u8222 \'84Articuli per diem\ldblquote  jeweils verdoppelt.}

