\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 133\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 136\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Orationes de passione Christi}}\plain \f1\lang1033\fs24 ]. (133\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Dominica die de omnibus vulneribus Christi\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnipotens sempiterne deus, qui humanum genus innumerabilibus viciis et persuasionibus diaboli sauciatum per multa vulnera dilectissimi filii}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 sanare voluisti\plain \f1\lang1033\fs24  \u8230 \'85 (134\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Feria 4\plain \f1\i\super\lang1033\fs24 a\plain \f1\i\lang1033\fs24  de quinque vulneribus\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Domine Ihesu Christe, fili dei vivi, qui de celis ad terram de sinu patris descendisti\plain \f1\lang1033\fs24  \u8230 \'85 Auch {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hs Berlin, SB, Ham. 63}}\plain \f1\lang1033\fs24 , 30\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Kat. Berlin Hamilton, S. 34. (135\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Feria 5\plain \f1\i\super\lang1033\fs24 a\plain \f1\i\lang1033\fs24  de lacrimis domini\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Deus, cuius unigenitus assumpte humanitatis probabile argumentum in resuscitacione beati Lazari lacrimando exhibuit\plain \f1\lang1033\fs24  \u8230 \'85 Leroquais, Livres d\rquote heures 2, S. 81. (135\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Alia oracio de passione Christi\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Domine deus, deus de deo, lumen de lumine, qui humanum genus crucis patibulo\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 redimere dignatus es\plain \f1\lang1033\fs24  \u8230 \'85 Druck: Antidotarius animae 1490, 38\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 \endash 39\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  (in der Hs grammatische Formen f\u252 \'fcr eine Beterin). Die \u252 \'fcbrigen Initien im Register.}

