\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 136\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 141\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 [Ps.-] Hieronymus}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Oratio de passione Christi}}\plain \f1\lang1033\fs24 . (136\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit oracio gloriosissimi doctoris sancti Iheronimi presbiteris. Feria secunda\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 In nomine domini omne genu flectatur celestium, terrestrium et infernorum}}\plain \f1\lang1033\fs24  \u8230 \'85 (139\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Conclusio dominice laudis amplitudine iocunda dominica die\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Gracias agimus tibi\plain \f1\lang1033\fs24  \u8230 \'85 Verglichen mit {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hs Berlin, SB, Lat. oct. 304}}\plain \f1\lang1033\fs24 , 93\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 99\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 : dort bei anderer Aufteilung auf die Wochentage vor den Orationen zus\u228 \'e4tzliche Preces eingeschoben. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 BHM}}\plain \f1\lang1033\fs24  Nr 956.}

