\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 141\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Pater-noster-Gebete}}\plain \f1\lang1033\fs24 . (141\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro peccatis quinque Pater noster\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Domine Ihesu Christe, hic sto ante oculos (141v) tuos tamquam pauper mendicus ante divitem}}\plain \f1\lang1033\fs24  \u8230 \'85, 2. \u8230 \'85 \plain \f1\i\lang1033\fs24 peccatrix maxima ante terribilem iudicem\plain \f1\lang1033\fs24  \u8230 \'85, 3. \u8230 \'85 \plain \f1\i\lang1033\fs24 servus ante dominum suum\plain \f1\lang1033\fs24  \u8230 \'85, 4. \u8230 \'85 \plain \f1\i\lang1033\fs24 amicus ante amicum\plain \f1\lang1033\fs24  \u8230 \'85, 5. \u8230 \'85 \plain \f1\i\lang1033\fs24 filius ante patrem\plain \f1\lang1033\fs24  \u8230 \'85\endash  (142\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24 a tua hereditate numquam separari permittas. Amen.\plain \f1\lang1033\fs24  Auch {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hs G\u246 \'f6ttingen, SuUB, Theol. 242e}}\plain \f1\lang1033\fs24 , 25\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 26\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , Kat. G\u246 \'f6ttingen Neuzug\u228 \'e4nge, S. 63; vgl. Kat. Niedersachsen 10, S. 11 (zu Hs Ebstorf, KlosterB, IV 4, 224\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) mit weiteren Nachweisen. Angeh\u228 \'e4ngt: (142\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ave domine Ihesu Christe, verbum patris, filius virginis}}\plain \f1\lang1033\fs24  \u8230 \'85 5 Ave-Gr\u252 \'fc\u223 \'dfe. Druck: Wilmart, Auteurs, S. 412. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Chevalier Nr 1844}}\plain \f1\lang1033\fs24 . Vgl. Leroquais, Livres d\rquote heures 2, S. 381 (Reg.).}

