\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 143\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 148\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Orationes de passione Christi}}\plain \f1\lang1033\fs24 ]. (143\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 147\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 [O] domine Ihesu Christe, in tua sacra vulnera me immergo}}\plain \f1\lang1033\fs24  \u8230 \'85 Es folgen mehrere kurze Anrufungen und Gebete; schlie\u223 \'dft: (145\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) [P]\plain \f1\i\lang1033\fs24 eto, domine, per spineum dyadema divini capitis tui, quo coronatus es in die leticie cordis tui\plain \f1\lang1033\fs24  \u8230 \'85; (147\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 148\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Gebet zu den 5 Wunden. [E]\plain \f1\i\lang1033\fs24 go peccatrix prosterno me ante te, summe rex laudabilis, et saluto tua quinque vulnera\plain \f1\lang1033\fs24  \u8230 \'85 Es folgen 5 Anrufungen: (147\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) [A]\plain \f1\i\lang1033\fs24 vete, o sanctissima quinque vulnera\plain \f1\lang1033\fs24  \u8230 \'85 und (148\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) kurzes Schlu\u223 \'dfgebet.}

