\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (13\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Kalenderregeln}}\plain \f1\lang1033\fs24 . (13\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De anno et partibus eius\plain \f1\lang1033\fs24 \u8249 \'8b. \u8230 \'85 \u8250 \'9b\plain \f1\i\lang1033\fs24 De numero nonarum\plain \f1\lang1033\fs24  \u8230 \'85\u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Walther, Initia}}\plain \f1\lang1033\fs24  17607. (13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De equinoctiis anni\plain \f1\lang1033\fs24  \u8230 \'85\u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Walther, Proverbia}}\plain \f1\lang1033\fs24  13432. (14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De quatuor anni temporibus\plain \f1\lang1033\fs24 \u8249 \'8b. Walther, Initia 4053 bzw. Proverbia 4968. \u8250 \'9b\plain \f1\i\lang1033\fs24 Ieiunia quatuor temporum anni\plain \f1\lang1033\fs24 \u8249 \'8b. Walther, Proverbia 21984. \u8250 \'9b\plain \f1\i\lang1033\fs24 Qualitates quatuor partium anni\plain \f1\lang1033\fs24 \u8249 \'8b. Walther, Proverbia 668a.}

