\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  Nachtr\u228 \'e4ge von 2 H\u228 \'e4nden: 1. {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Strafandrohung bei Vergehen von Angeh\u246 \'f6rigen des Pr\u228 \'e4monstratenserordens}}\plain \f1\lang1033\fs24 . (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Autoritate dei omnipotentis, patris et filii et spiritus sancti, et autoritate Petri et Pauli}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Lucie, Agnetis, Genofefe et omnium virginum et autoritate ordinis excommunicamus, anatematisamus et a limitibus ecclesie sancte sequestramus omnes canonicos\plain \f1\lang1033\fs24  \u8230 \'85 Ausf\u252 \'fchrliche Fassung. (1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Verk\u252 \'fcrzte Fassung ohne Anrufung der Heiligen. F\u252 \'fcr die Vergehen vgl. die Schlu\u223 \'dfbestimmung in den Akten des Generalkapitels von 1502: Acta et Decreta Capitulorum Generalium Ordinis Praemonstratensis. Bd 2: 1501\endash 1530. Ed. J.B. Valvekens, Averbode 1969, S. 31.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) 2a. {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Reisesegen}}\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Valete in eo, qui est vere filius Marie virginis}}\plain \f1\lang1033\fs24  \u8230 \'85 2b. {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 \u220 \'dcber die Aufnahme von Kanonikern oder Konversen}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quia quidam canonici ordinis nostri opponunt se abbatibus suis, volentibus recipere canonicum vel conversum}}\plain \f1\lang1033\fs24  \u8230 \'85}

