\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Eingeschoben: (21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930gi/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Symbolum fidei Athanasij Alexandrini episcopi}}\plain \f1\lang1033\fs24 \u8249 \'8b. Quicumque vult. (22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Preces}}\plain \f1\lang1033\fs24  f\u252 \'fcr die Prim. (24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 25\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) [{\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Officium capituli}}\plain \f1\lang1033\fs24 ]. \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Post prima msancte Marie pronunciatur datarium kalendarij et luna cum festivitate sequentis diej}}\plain \f1\lang1033\fs24 \u8249 \'8b. \u8230 \'85 \plain \f1\i\lang1033\fs24 Preciosa in conspectu\plain \f1\lang1033\fs24  \u8230 \'85 (26\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 27\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) [\plain \f1\scaps\lang1033\fs24 Preces minores\plain \f1\lang1033\fs24 ] f\u252 \'fcr die kleinen Horen. (41\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 42\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) [\plain \f1\scaps\lang1033\fs24 Preces\plain \f1\lang1033\fs24 ] f\u252 \'fcr Laudes und Vesper. Versikelpaare wie 27\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; mit anschlie\u223 \'dfenden Suffragien f\u252 \'fcr die Laudes: (42\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Dein pro sancto Georgio\plain \f1\lang1033\fs24  \u8230 \'85\u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro sancto Maurelio\plain \f1\lang1033\fs24  \u8230 \'85\u8249 \'8b, zu Heilig Kreuz, den Apostel, um Frieden. (104\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24 ) Suffragien f\u252 \'fcr die Vesper: zu den Aposteln, \u8250 \'9b\plain \f1\i\lang1033\fs24 Postea de sancto Georgio\plain \f1\lang1033\fs24  \u8230 \'85\u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 Pro sancto Maurelio\plain \f1\lang1033\fs24  \u8230 \'85\u8249 \'8b, um Frieden. (106\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 107\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) [\plain \f1\scaps\lang1033\fs24 Preces\plain \f1\lang1033\fs24 ] f\u252 \'fcr die Komplet.}

