\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Bernardus Claraevallensis}}\plain \f1\scaps\lang1033\fs24 : \plain \f1\scaps\lang1033\fs24 Sermones de diversis\plain \f1\lang1033\fs24 ], {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Sermo 66}}\plain \f1\lang1033\fs24 , Exzerpt. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Tria sunt que sanctum hominem faciunt}}\plain \f1\lang1033\fs24  \u8230 \'85 Ed.: Opera. Rec. J. Leclercq, H. Rochais, Bd 6/1, Rom 1970, S. 297 Z. 10 \endash  S. 298 Z. 3.}

