\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 127\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Feria quinta ad matutinas}}\plain \f1\lang1033\fs24 \u8249 \'8b. Bis auf die Komplet auch Hs {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Weimar Oct 62}}\plain \f1\lang1033\fs24 , 52\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 63\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 . (123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O beatissima Maria, virgo et mater domini nostri Ihesu Christi, salvatoris nostri, flos et ianua paradisi}}\plain \f1\lang1033\fs24  \u8230 \'85 (123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 124\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio beati Augustini ad primam\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Supplico tibi, o virgo Maria, mater summe benignitatis, per illam inestimabilem leticiam}}\plain \f1\lang1033\fs24  \u8230 \'85 Vgl. \u220 \'dcberlieferung Augustinus X/1, S. 410 Nr 12. (124\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Ad terciam\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ave candidum lilium fulgide semperque tranquille}}\plain \f1\i\lang1033\fs24  trinitatis\plain \f1\lang1033\fs24  \u8230 \'85 Vgl. Hs {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Frankfurt, StuUB, Ms. Praed. 169}}\plain \f1\lang1033\fs24 , 315\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , Kat. Frankfurt 2.1, 379. Auch {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Theol. lat. oct. 188}}\plain \f1\lang1033\fs24 , 141\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 . (124\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 125\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Ad sextam\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Eya mater pie prolis, Ihesum, florem ex te natum, o Maria, placa nobis}}\plain \f1\lang1033\fs24  \u8230 \'85 (125\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 126\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Anselmus Cantuariensis}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Oratio 6}}\plain \f1\lang1033\fs24 ], Exzerpt. \u8250 \'9b\plain \f1\i\lang1033\fs24 Ad nonam\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Virgo mundi venerabilis, mater humano genere amabilis, femina angelis mirabilis }}\plain \f1\lang1033\fs24 \u8230 \'85 Ed.: Opera omnia. Rec. F.S. Schmitt, Bd 3, Edinburg 1946, S. 15f. Z. 4\endash 48; Barr\u233 \'e9, Pri\u232 \'e8res, S. 300f. Nr 74 Abschnitt 1\endash 2 (in dieser Hs mit kleinen Auslassungen, am Schlu\u223 \'df abweichend). Vgl. Wilmart, Auteurs, S. 480. (126\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 127\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Ad vesperas\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Regina celi, ianua paradisi, mater misericordie, sancta Maria, tu excelsior celis, sublimior}}\plain \f1\lang1033\fs24  (126\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 angelis\plain \f1\lang1033\fs24  \u8230 \'85 (127\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Ad completorium\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Tu es porta paradisi, ianua celi, tu templum domini}}\plain \f1\lang1033\fs24  \u8230 \'85 Darunter Verweisung: \u8250 \'9b\plain \f1\i\lang1033\fs24 Feria sexta querere post VI folia\plain \f1\lang1033\fs24 \u8249 \'8b.}

