\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 12\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Orationes de passione Christi}}\plain \f1\lang1033\fs24 . (2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio de vulnere Christi, quod habuit in scapula sua\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O domine Ihesu Christe, agne dei, ego indigna famula tua saluto illud sanctissimum vulnus}}\plain \f1\lang1033\fs24  \u8230 \'85 Auch {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hs Ebstorf, KlosterB, IV 5}}\plain \f1\lang1033\fs24 , 270\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Kat. Niedersachsen, 10, S. 34.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Innocencius papa quartus concessit omnibus dicentibus remissionem omnium peccatorum suorum\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Deus, qui pro redempcione mundi nasci et circumcidi voluisti et a iudeis reprobari}}\plain \f1\lang1033\fs24  \u8230 \'85 Druck: Antidotarius animae 1490, 38\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 . Leroquais, Livres d\rquote heures 1, S. 258; 2, S. 39.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 12\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oraciones ad singula membra Christi et primo ad pedes\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O speciosi pedes domini mei Ihesu Christi}}\plain \f1\lang1033\fs24  \u8230 \'85 Zyklus von 13 Gebeten, jeweils mit Pater noster und Ave Maria. U.a. auch Hs Ebstorf, KlosterB, IV 5, 24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , Kat. Niedersachsen 10, S. 23.}

