\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 12\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gebete f\u252 \'fcr verschiedene Wochentage}}\plain \f1\lang1033\fs24 . (12\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Feria sexta ad IX legas psalmum stando\plain \f1\lang1033\fs24 \u8249 \'8b. Ps 30,1\endash 6 (nur Anfang). \u8250 \'9b\plain \f1\i\lang1033\fs24 Fac veniam et dic hanc oracionem\plain \f1\lang1033\fs24 \u8249 \'8b. (12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 In illa fidelissima commendacione, qua deo patri sanctissimum spiritum tuum}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 commendasti\plain \f1\lang1033\fs24  \u8230 \'85
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Quatuor temporum feria quarta dic hanc sequentem oracionem\plain \f1\lang1033\fs24 \u8249 \'8b. (14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Domine sancte pater, suscipe hanc oracionem, quam tibi offero in honorem (!) illius eterne et immense laudis}}\plain \f1\lang1033\fs24  \u8230 \'85 (14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Deinde lege xxx Pater noster\plain \f1\lang1033\fs24  \u8230 \'85\u8249 \'8b. Folgen 2 Gebete, Initien im Register.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Feria sexta pro pena sustinenda in tricesimo dic\plain \f1\lang1033\fs24  (20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 sequentem oracionem\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Domine sancte pater, suscipe hanc oracionem, quam tibi offero in honore eterne et immense graciarum accionis}}\plain \f1\lang1033\fs24  \u8230 \'85 (20\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Deinde lege xxx Pater noster\plain \f1\lang1033\fs24  \u8230 \'85\u8249 \'8b und die Gebete wie 14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sabbato pro pena in primo anno sufferenda dic hanc oracionem\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Domine sancte pater, suscipe hanc oracionem, quam tibi offero in honore[m] illius eterne desiderabilitatis}}\plain \f1\lang1033\fs24  \u8230 \'85 (22\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Deinde\plain \f1\lang1033\fs24  (22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 lege xxx Pater noster\plain \f1\lang1033\fs24  \u8230 \'85\u8249 \'8b und die Gebete wie 14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 . Schlie\u223 \'dft mit Ps 30,1\endash 6 (nur Anfang) und einem weiteren Gebet, Initium im Register.}

