\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 38\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gebete zur Vorbereitung auf den Empfang der Kommunion}}\plain \f1\lang1033\fs24 . \u8250 \'9b\plain \f1\i\lang1033\fs24 Quicumque desideras digne corpus dominicum suscipere, stude te preparare ante novem dies. Primo die recogi\plain \f1\lang1033\fs24 (24\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24 ta in amaritudine cordis tui\plain \f1\lang1033\fs24  \u8230 \'85\u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Paratum cor meum, domine, paratum cor meum sit, ut tibi serviat}}\plain \f1\lang1033\fs24  \u8230 \'85 \u8250 \'9b\plain \f1\i\lang1033\fs24 Deinde hos tres versus\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Eya Ihesu desiderantissime,\plain \f1\lang1033\fs24  (25\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 tam violenter trahe me\plain \f1\lang1033\fs24  \u8230 \'85 Auf diese f\u252 \'fcr alle Tage gleichbleibende Einleitung folgen Gebete, Initien im Register, ab dem 2. Tag au\u223 \'dferdem Psalmen mit (28\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Versus}}\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O desiderate cordis mei milies (!) delicatissime}}\plain \f1\lang1033\fs24  \u8230 \'85 Schlie\u223 \'dft jeweils mit Versikel und (26\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Da mihi, domine, spiritum vehementem in contritione}}\plain \f1\lang1033\fs24  \u8230 \'85, bzw. am 9. Tag: (38\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio sequitur\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Festinantes, omnipotens deus, in occursum filii tui domini nostri Ihesu Christi nulli impediant actus terreni}}\plain \f1\lang1033\fs24  \u8230 \'85}

