\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 38\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 70\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Orationes ante communionem}}\plain \f1\lang1033\fs24 . (38\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Cum volueris communicare, dic precedenti die hanc oracionem\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Per memoriam illius misericordie, qua tu, Ihesu bone, venisti in mundum}}\plain \f1\lang1033\fs24  \u8230 \'85
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Lege ante communionem\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Rogo te, domine Ihesu Christe clementissime, per piissimum cordis tui cogita}}\plain \f1\lang1033\fs24 (39\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24 tum, quo omne seculum precogitasti\plain \f1\lang1033\fs24  \u8230 \'85; (40\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O Maria, mater misericordie, per puritatem cordis tui amove a corde meo omnes noxias cogitaciones}}\plain \f1\lang1033\fs24  \u8230 \'85 Zyklus von 8 Gebeten (oculi, aures, vox, vultus, extensio in cruce, pedes, mors), auf die jeweils ein kurzes Gebet zu Maria und ein Psalm folgen. Schlie\u223 \'dft: (51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 O pincerna, nobilissime spiritus sancte paraclite, propinans fidelibus gratie tue nectar salutare, veni, dulcissime consolator\plain \f1\lang1033\fs24  \u8230 \'85 (51\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Letania\plain \f1\lang1033\fs24 \u8249 \'8b. Zu den einzelnen Heiligenst\u228 \'e4nden. (54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CO}}\plain \f1\lang1033\fs24  Nr 800e. (Variante) und eine weitere Kollekte.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 58\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oracio\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ad mensam dulcissimi convivii tui, domine Ihesu Christe, accedere vereor}}\plain \f1\lang1033\fs24  \u8230 \'85 Nur am Anfang mit dem bekannten Gebet \u252 \'fcbereinstimmend. Es folgen (58\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 70\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) zahlreiche, teils k\u252 \'fcrzere Gebete zu Gott, Christus, Maria und den Heiligen, Initien im Register.}

