t HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hs Darmstadt, LuHB, Hs 2273}}\plain \f1\lang1033\fs24 , 122\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , Kat. Darmstadt 3, S. 66 (Nr 7).}

