\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ordnung der Nokturn-Psalmen}}\plain \f1\lang1033\fs24 : \u8250 \'9b\plain \f1\i\lang1033\fs24 In sacratissima nocte paschali\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 In nocte ascensionis\plain \f1\lang1033\fs24 \u8249 \'8b. \u8250 \'9b\plain \f1\i\lang1033\fs24 In nocte pe\plain \f1\lang1033\fs24 [n]\plain \f1\i\lang1033\fs24 thecoste\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De uno martire et confessore\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De martiribus\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De virginibus\plain \f1\lang1033\fs24 \u8249 \'8b. Vgl. Breviarium Cisterciense 1484.}

