\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 59\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 90\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Casus fratris Clari}}\plain \f1\lang1033\fs24 ]. (59\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 61\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Utrum quilibet teneatur ad solutionem cunctarum decimarum, si non est in terra consuetudo solvendi\plain \f1\lang1033\fs24 \u8249 \'8b. Kapitelverzeichnis. (61\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De solutione decimarum.\plain \f1\lang1033\fs24  [Casus] \plain \f1\i\lang1033\fs24 I\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Utrum quilibet teneatur absolutionem (recte: ad solutionem) cunctarum decimarum, si non est in terra consuetudo solvendi}}\plain \f1\i\lang1033\fs24 .\plain \f1\lang1033\fs24  \u8230 \'85 (89\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De quadam alia irregularitatem\plain \f1\lang1033\fs24  (!). [Casus] \plain \f1\i\lang1033\fs24 CXLVII\plain \f1\lang1033\fs24 \u8249 \'8b. \u8230 \'85 (90\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24 homicida sum quantumcumque licite fecerim.\plain \f1\lang1033\fs24  \u8250 \'9b\plain \f1\i\lang1033\fs24 Forma absolutionis usurarii. CXLVIII\plain \f1\lang1033\fs24 \u8249 \'8b. \u8230 \'85\endash  (90\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24 et debet iurare mandata ecclesie et facere secundum consuetudinem terre. Deo gratias. Amen.\plain \f1\lang1033\fs24  Mit Teildruck: Fran\u231 \'e7ois-Marie Henquinet, Claire de Florence, O.F.M., Canoniste et penitentier pontifical vers le milieu du XIII\plain \f1\super\lang1033\fs24 e\plain \f1\lang1033\fs24  si\u232 \'e8cle, in: Archivum Franciscanum Historicum 32, 1939, S. 3\endash 48, bes. 40\endash 42 zur Verfasserfrage. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Michaud-Quantin, Sommes de casuistique}}\plain \f1\lang1033\fs24 , S. 52f. {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Mohan, Initia}}\plain \f1\lang1033\fs24 , S. 468*. {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bloomfield/ Guyot}}\plain \f1\lang1033\fs24  Nr 6278. {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hamesse, Repertorium initiorum}}\plain \f1\lang1033\fs24 , Nr 35092.}

