\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 91\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 103\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat18 De septem sacramentis}}\plain \f1\lang1033\fs24 . Unvollst\u228 \'e4ndig wegen Blattverlusts: Textl\u252 \'fccke im Kapitel \u252 \'fcber die Eucharistie. (91\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit de septem sacramentis\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Nota quod sacramenta quedam sunt ordinata in remedium culpe, quedam in remedium pene. Culpa autem triplex}}\plain \f1\lang1033\fs24  \u8230 \'85 \u8250 \'9b\plain \f1\i\lang1033\fs24 De baptismo\plain \f1\lang1033\fs24 \u8249 \'8b. \u8230 \'85 (93\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De sacramento confirmationis\plain \f1\lang1033\fs24 \u8249 \'8b. \u8230 \'85 (93\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De sacramento heucaristie\plain \f1\lang1033\fs24 \u8249 \'8b. \u8230 \'85 (102\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De sacramento penitentie\plain \f1\lang1033\fs24 \u8249 \'8b. \u8230 \'85 (103\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De sacramento extreme unctionis\plain \f1\lang1033\fs24 \u8249 \'8b. \u8230 \'85 \plain \f1\i\lang1033\fs24 quia possunt habere multa\plain \f1\lang1033\fs24  \u9553 \'a6 \u8230 \'85 Bricht ab.}

