\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (22\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 237\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat18 Summa de paenitentia}}\plain \f1\lang1033\fs24 , recensio secunda. (22\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit summa magistri Raimundi de penitentia\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quoniam, ut ait Ieronimus, secunda post naufragium tabula est culpam simpliciter confiteri}}\plain \f1\lang1033\fs24  \u8230 \'85 (22\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Text: \u8250 \'9b\plain \f1\i\lang1033\fs24 De symonia\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quoniam inter crimina ecclesiastica symoniaca heresis optinet primum locum}}\plain \f1\lang1033\fs24  \u8230 \'85\endash  (237\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24 Venite, benedicti, percipite regnum. Amen.\plain \f1\lang1033\fs24  \u8250 \'9b\plain \f1\i\lang1033\fs24 Explicit summa fratris Raimundi de penitentia\plain \f1\lang1033\fs24 \u8249 \'8b. In den Seitentiteln gez\u228 \'e4hlt als \plain \f1\i\lang1033\fs24 Liber I\endash III\plain \f1\lang1033\fs24 . Ed.: Xaverius Ochoa u. Aloisius Diez, Universa Bibliotheca Iuris 1B, Rom 1976, Sp. 277\endash 884. Zu Autor und Werk: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Kaeppeli, Scriptores OP, }}\plain \f1\lang1033\fs24 Nr 3407. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Bloomfield/Guyot}}\plain \f1\lang1033\fs24  Nr 5054. {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Newhauser/Bejczy}}\plain \f1\lang1033\fs24  Nr 5054. {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Hamesse, Repertorium initiorum}}\plain \f1\lang1033\fs24 , Nr 28735/28337 (jeweils ohne diese Hs). Stephan Kuttner, Zur Entstehungsgeschichte der \u8222 \'84Summa de casibus poenitentiae\ldblquote  des hl. Raymund von Penyafort, in: Zeitschrift der Savigny-Stiftung f\u252 \'fcr Rechtsgeschichte. Kanonistische Abteilung 39, 1953, S. 419\endash 434. {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Michaud-Quantin, Sommes de casuistique}}\plain \f1\lang1033\fs24 , S. 34\endash 42.}

