\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 10\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat18 Basilius Caesariensis}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat18 In Gordium martyrem}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 2\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Widmungsvorwort des \u220 \'dcbersetzers: \u8250 \'9b\plain \f1\i\lang1033\fs24 Pontifici maximo N\plain \f1\lang1033\fs24 [icolao] \plain \f1\i\lang1033\fs24 quinto. \plain \f2\i\lang1024\fs24 In magni Basilij C\u281 \'ea\plain \f1\i\lang1033\fs24 sare\plain \f2\i\lang1024\fs24 \u281 \'ea Cappadocie a\plain \f1\i\lang1033\fs24 rchiepiscopi in sanctum martyrem Gordium encomium prologus\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 [B]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 asilium C\u281 esare\u281 e Cappadoci\u281 e archiepiscopum cognomento ,magnum\lquote  Gregorius Constantinopoleos Patriarcha cognomento \u8218 \'82theologus\lquote  in epitaphio, quod in eum luculentissimo sermone descripsit}}\plain \f1\lang1033\fs24  \u8230 \'85 (2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) bis auf wenige Zeilen leer. (3\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 \endash 10\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Text. \u8250 \'9b\plain \f2\i\lang1024\fs24 Magni Basilij C\u281 \'easare\u281 \'ea\plain \f1\i\lang1033\fs24  Cappadocie archiepiscopi in sanctum martyrem Gordium encomium prooemium\plain \f1\lang1033\fs24 \u8249 \'8b. [{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 L]}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 ex inest apibus a natura, ne sese prius ab alvearibus extollere quam earum rex evolationem eis denunciet [corr. ex denunctiet}}\plain \f1\lang1033\fs24 ] \u8230 \'85 Verwendung von e-caudata unregelm\u228 \'e4\u223 \'dfig. F\u252 \'fcr den griech. Grundtext vgl. PG 31, Sp. 489\endash 508. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 CPG}}\plain \f1\lang1033\fs24  Nr 2862. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 BHG}}\plain \f1\lang1033\fs24  u. BHG Auct. Nr 703. Anonyme lat. \u220 \'dcbersetzung, als \plain \f1\i\lang1033\fs24 primitias\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Papst Nikolaus V.}}\plain \f1\lang1033\fs24  (*1397, \u8224 \'861455, gew\u228 \'e4hlt 1447) gewidmet, \plain \f2\i\lang1024\fs24 captato sub tu\u281 \'ea amplissim\u281 \'ea umbr\u281 \'ea protectione tranquillo\plain \f1\i\lang1033\fs24  hac hyeme ocio\plain \f1\lang1033\fs24  (1\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) begonnen. Der \u220 \'dcbersetzer berichtet, da\u223 \'df \plain \f1\i\lang1033\fs24 hijs forte die\plain \f2\i\lang1024\fs24 bus sacr\u281 \'ea s[c]ilicet quadragesimalis observanti\u281 \'ea de tu\u281 \'ea studiossim\u281 \'ea san\plain \f1\i\lang1033\fs24 ctitatis interpretibus unus \endash  qui die noctuque te iubente ista perquirunt \endash  inter alios non mediocris Theodorus meam visitationis gratia cellulam ingressus est\plain \f1\lang1033\fs24  (1\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) und den Text gelesen hat. Kristeller (s. Lit.) erw\u228 \'e4gt, da\u223 \'df mit diesem \u8222 \'84Interpres\ldblquote  Theodorus Gaza (* um 1400, \u8224 \'86 um 1475) gemeint sei. Dieser hielt sich seit 1450 in Rom auf, s. Dizionario biografico degli Italiani 52, Rom 1999, S. 737\endash 746 (C. Bianca). Wenig wahrscheinlich dagegen die Vermutung von Fedwick, Bibliotheca Basiliana, aaO., S. 1074 Anm. 53, es k\u246 \'f6nne sich um den Schreiber Theodorus Buckinch handeln. Ein Hinweis auf diese \u220 \'dcbersetzung auch in: Ausst.Kat. Umanesimo e Padri della Chiesa. Manoscritti e incunaboli di testi patristici da Francesco Petrarca al primo Cinquecento. A cura di Sebastiano Gentile (Ausstellung Florenz Biblioteca Medicea Laurenziana 1997), Rom 1997, S. 285 (zu Nr 65).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (10\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Nachtrag: [{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat18 Tractus in feria quarta cinerum}}\plain \f1\lang1033\fs24 ]. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Domine, non secundum peccata nostra, que fecimus}}\plain \f1\lang1033\fs24  \u8230 \'85 Wie MR (mit 1. Versikel). [{\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat18 Collecta}}\plain \f1\lang1033\fs24 ]. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Deus, qui de beate Marie virginis utero verbum tuum angelo anunciante (!) carnem suscipere voluisti, tribue quesumus}}\plain \f1\lang1033\fs24  \u8230 \'85 Anfang wie {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 CO}}\plain \f1\lang1033\fs24  Nr 1518.
