\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 60\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Collectio auctoritatum}}\plain \f1\lang1033\fs24 . Titel im Inhaltsverzeichnis (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ): \plain \f1\i\lang1033\fs24 Item quedam excerpta ex libris eiusdem doctoris\plain \f1\lang1033\fs24  [i.e. Bernardi] \plain \f1\i\lang1033\fs24 ac aliorum.\plain \f1\lang1033\fs24  F\u252 \'fcr die kurzen Augustinus-Exzerpte vgl. auch {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u220 \'dcberlieferung Augustinus}}\plain \f1\lang1033\fs24  X/1, S. 441 Nr 76.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Auctoritates\plain \f1\lang1033\fs24 . (16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipiunt auctoritates beati Bernardi\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O homo, quid sollicitus es de regali edifitio? Deus tuus iacet in presepio}}\plain \f1\i\lang1033\fs24 .\plain \f1\lang1033\fs24  \u8230 \'85 Aus: [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Thomas Cisterciensis}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Commentarius in Cantica Canticorum}}\plain \f1\lang1033\fs24 ], lib. 1. PL 206, Sp. 27, Z. 14\endash 21. \plain \f1\i\lang1033\fs24 Providentia: Vita confert meritum.\plain \f1\lang1033\fs24  \u8230 \'85 Vgl. Bernardus Claraevallensis. Opera. Rec. J. Leclercq, H. Rochais, Bd 6/2, Rom 1972, S. 141, Z. 4. \plain \f1\i\lang1033\fs24 Stabilitas: Divina clementia cooperante intra septa monasterij et prescriptos terminos simus stabiles\plain \f1\lang1033\fs24  \u8230 \'85\endash  (16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24 et palmam consummationis obtinuerit.\plain \f1\lang1033\fs24  Vgl. [{\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Eusebius \u8218 \'82Gallicanus\lquote }}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Collectio homiliarum}}\plain \f1\lang1033\fs24 ], Hom. 40, CC 101A, S. 482, Z. 209\endash 212. \u8230 \'85 \plain \f1\i\lang1033\fs24 Sotius Ihesus: O domine Ihesu, quam bonus socius es in via, dulcis ad confabulandem\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 O homo, si te delectant, que sub celo sunt\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 inmortales et beati qualiter remunerandi sunt.\plain \f1\lang1033\fs24  Vgl. [{\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Ambrosius Autpertus}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Libellus de conflictu vitiorum atque virtutum}}\plain \f1\lang1033\fs24 ], cap. 26. CCCM 27B, S. 928, Z. 17\endash 22. \plain \f1\i\lang1033\fs24 Castitas periclitatur in delicijs\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 caritas in hoc seculo nequam?\plain \f1\lang1033\fs24  Vgl. Bernardus Claraevallensis. Opera. Rec. J. Leclercq, H. Rochais, Bd 4, Rom 1966, S. 113, Z. 14f. \u8230 \'85 (17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24 Passiones cordis: Felix, qui passiones cordis sui propter iustitias ordinat\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 et in ore versetur gratiarum actio et vox laudis.\plain \f1\lang1033\fs24  Vgl. Bernardus Claraevallensis. Opera. Rec. J. Leclercq, H. Rochais, Bd 5, Rom 1968, S. 66, Z. 10\endash 13.}

