\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 De quindecim gradibus perfectionis}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  (19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De xv gradibus perfectionis\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quindecim sunt gradus perfectionis: Meditatio mortis, contemptus temporalium}}\plain \f1\lang1033\fs24  \u8230 \'85 Folgen Verhaltensregeln f\u252 \'fcr Novizen: \plain \f1\i\lang1033\fs24 Item, fili, silentium teneas, oculos vagos non habeas\plain \f1\lang1033\fs24  \u8230 \'85 (19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Nota\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 quod quatuor genera hominum solent sedere, scilicet iudicantes, commedentes, meditantes et quiescentes\plain \f1\lang1033\fs24  \u8230 \'85 Zitiert werden: (20\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Augustinus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hieronymus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Gregorius}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bernardus Claraevallensis}}\plain \f1\lang1033\fs24 .}

