\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 28\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Ps.-Bernardus Claraevallensis}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 De interiori domo seu de conscientia aedificanda}}\plain \f1\lang1033\fs24 ], cap. 27 (umgestellt). 38. 4\endash 5. 8\endash 10. 1 (verk\u252 \'fcrzt). Prolog. cap. 2 (verk\u252 \'fcrzt). (24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Quomodo tempore orationis malis cogitationibus sit resistendum\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cum ad cor meum redire volo, desideriorum carnalium turbe tumultusque vitiorum temptationibus cogitationem dum dissipant}}\plain \f1\lang1033\fs24  \u8230 \'85\endash  (24\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 et in illo vere felicitatis fonte desiderium suum collocare.\plain \f1\lang1033\fs24  \u8250 \'9b\plain \f1\i\lang1033\fs24 Item meditatio bona\plain \f1\lang1033\fs24 \u8249 \'8b. (25\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Scire vellem, qualis ipse sum, sed vix vera de me ipso cernere possum\plain \f1\lang1033\fs24  \u8230 \'85 (25\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De mundo corde\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Sequitur, ut eum, a quo tanta benefitia accepimus\plain \f1\lang1033\fs24  \u8230 \'85 (26\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De libero animo\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Animus sit liber a mundi sollicitudinibus\plain \f1\lang1033\fs24  \u8230 \'85 (26\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De ratione illuminata\plain \f1\lang1033\fs24 \u8249 \'8b. \u8230 \'85 \u8250 \'9b\plain \f1\i\lang1033\fs24 De bona conscientia\plain \f1\lang1033\fs24 \u8249 \'8b. \u8230 \'85 (27\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Quod bonum sit redire ad conscientiam\plain \f1\lang1033\fs24 \u8249 \'8b. \u8230 \'85 (27\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Quomodo mundanda sit conscientia\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Hec ergo conscientia, in qua perpetuo anima mansura est\plain \f1\lang1033\fs24  \u8230 \'85 (28\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Hec domus, in qua habitamus\plain \f1\lang1033\fs24  \u8230 \'85 \u8250 \'9b\plain \f1\i\lang1033\fs24 De bona voluntate\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Inter omnia dona dei, que ad salutem hominis spectare videntur\plain \f1\lang1033\fs24  \u8230 \'85 Schlie\u223 \'dft: (28\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De propria voluntate\plain \f1\lang1033\fs24 \u8249 \'8b. \plain \f1\i\lang1033\fs24 Magnum malum est propria voluntas\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 dum aliene voci subdimur, nosmetipsos in corde superamus.\plain \f1\lang1033\fs24  Druck: PL 184, Sp. 536D\endash 537B. 536A\endash C. 545C\endash 546D. 512A\endash C. 515C\endash 517A. 509A\endash C. 507C\endash 509A. 511A\endash C. CPPM 2, Nr 3089. Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Glorieux, Pour revaloriser Migne}}\plain \f1\lang1033\fs24 , S. 71. {\fiel