\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 75\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 88\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 De virtutibus herbarum}}\plain \f1\lang1033\fs24 . Titel im Inhaltsverzeichnis (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ): \plain \f1\i\lang1033\fs24 Item libellus de virtutibus herbarum.\plain \f1\lang1033\fs24  (75\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 De ligno aloe}}\plain \f1\lang1033\fs24\chcbpat17 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Lignum enim multum est medicinale. Est enim lignum aloe triplex. Primum est valde ponderosum, quod est nodosum}}\plain \f1\i\lang1033\fs24 , et valde aromaticum et est subamari saporis et subnigri coloris et subrufi et contritioni dentium non resistens\plain \f1\lang1033\fs24  \u8230 \'85 Es folgen: (75\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De aneto\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De aniso\plain \f1\lang1033\fs24 \u8249 \'8b, (76\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De zinzibero\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De zeduario\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De zuochara\plain \f1\lang1033\fs24 \u8249 \'8b [kleines o \u252 \'fcber u], (76\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De galbano\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De gariophilis\plain \f1\lang1033\fs24 \u8249 \'8b, (77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De cinamonio\plain \f1\lang1033\fs24 \u8249 \'8b, (77\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De cardomomo\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De croco\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De cimino\plain \f1\lang1033\fs24 \u8249 \'8b, (78\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8222 \'84Mala granata\ldblquote , (78\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De pipere\plain \f1\lang1033\fs24 \u8249 \'8b, (79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De iunipero\plain \f1\lang1033\fs24 \u8249 \'8b, (79\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De ysopo\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De rutha\plain \f1\lang1033\fs24 \u8249 \'8b, (80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De polegio\plain \f1\lang1033\fs24 \u8249 \'8b, (81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De mentha\plain \f1\lang1033\fs24 \u8249 \'8b, (81\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De calamento\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De feniculo\plain \f1\lang1033\fs24 \u8249 \'8b, (82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De petrosilinio\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De porro\plain \f1\lang1033\fs24 \u8249 \'8b, (82\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De lactuca\plain \f1\lang1033\fs24 \u8249 \'8b, (83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De apio\plain \f1\lang1033\fs24 \u8249 \'8b, (83\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De absinthio\plain \f1\lang1033\fs24 \u8249 \'8b, (84\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De allio\plain \f1\lang1033\fs24 \u8249 \'8b, (84\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De cepe\plain \f1\lang1033\fs24 \u8249 \'8b, (85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De sinapi\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De arthemesia\plain \f1\lang1033\fs24 \u8249 \'8b, (85\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De coloquintida\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De cucurbita\plain \f1\lang1033\fs24 \u8249 \'8b. Bricht ab. (86\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Setzt wieder ein im Abschnitt \u8222 \'84De caule\ldblquote  (?), \u8250 \'9b\plain \f1\i\lang1033\fs24 De castanea\plain \f1\lang1033\fs24 \u8249 \'8b, (86\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De nuce\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De nuce avellana\plain \f1\lang1033\fs24 \u8249 \'8b, (87\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De uva immatura\plain \f1\lang1033\fs24 \u8249 \'8b, \u8250 \'9b\plain \f1\i\lang1033\fs24 De vino\plain \f1\lang1033\fs24 \u8249 \'8b, (88\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De vino rubeo\plain \f1\lang1033\fs24 \u8249 \'8b. (88\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Schlie\u223 \'dft mit \u8250 \'9b\plain \f1\i\lang1033\fs24 De novo musto\plain \f1\lang1033\fs24 \u8249 \'8b. \u8230 \'85 \plain \f1\i\lang1033\fs24 quia ab extremitate novi et veteris magis est remotum, quia illud maxime est temperatum.\plain \f1\lang1033\fs24  \u8250 \'9b\plain \f1\i\lang1033\fs24 Explicit liber\plain \f1\lang1033\fs24 \u8249 \'8b. Fast alle Pflanzen geh\u246 \'f6ren zwar zum Grundbestand des \u8222 \'84Circa instans\ldblquote , doch bestehen von gelegentlichen Parallelen \endash  besonders bei den Prim\u228 \'e4rqualit\u228 \'e4ten und den \u8222 \'84virtutes\ldblquote  sowie in den Abschnitten \u8222 \'84lignum aloe\ldblquote , \u8222 \'84apium\ldblquote  u. \u8222 \'84gariophili\ldblquote  \endash  abgesehen, keine \u220 \'dcbereinstimmungen mit diesem Pflanzenbuch; vgl. Hans W\u246 \'f6lfel, Das Arzneidrogenbuch \u8222 \'84Circa instans\ldblquote  in einer Fassung des XIII. Jahrhunderts aus der Universit\u228 \'e4tsbibliothek Erlangen. Text und Kommentar als Beitrag zur Pflanzen- und Drogenkunde des Mittelalters. Math.-naturw. Diss. Berlin 1939, S. 1\endash 118. M\u246 \'f6glicherweise ist das \u8222 \'84Circa instans\ldblquote  als eine Quelle des Textes (neben anderen, die noch zu ermitteln w\u228 \'e4ren) benutzt worden. F\u252 \'fcr das Kapitel \u8222 \'84De vino\ldblquote  lassen sich \u220 \'dcbereinstimmungen mit dem Abschnitt \u252 \'fcber den Wein im Breslauer Codex Salernitanus aufzeigen, s. Fritz Wolfgang Klaus, Die Abschnitte \u252 \'fcber Milch und Wein aus dem \u8222 \'84Liber simplicium medicinarum\ldblquote  (Platearius) im Breslauer Codex Salernitanus. Med. Diss. Leipzig 1920, bes. S. 5\endash 10.}

