\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 91\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 112\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Thomas de Aquino}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 De rationibus fidei}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Beatus [Petrus] apostolus, qui promissione[m] accepit a domino}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 que alibi diligentius pertractata sunt.\plain \f1\lang1033\fs24  \u8250 \'9b\plain \f1\i\lang1033\fs24 Explicit tractatus sancti Thome de Aquino contra Sarracenos\plain \f1\lang1033\fs24 \u8249 \'8b. Ed.: Opera omnia. Leonina, Bd 40, pars B, Rom 1968, S. B57\endash B73. Zur handschriftl. \u220 \'dcberlieferung: ebd., S. B8\endash B36, bes. B8, B19, B26f. (Sigle B\plain \f1\super\lang1033\fs24 8\plain \f1\lang1033\fs24  = diese Hs). {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Glorieux, Ma\u238 \'eetres}}\plain \f1\lang1033\fs24 , Nr 14af. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Dondaine/Shooner}}\plain \f1\lang1033\fs24  Nr 242 (diese Hs). {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hamesse, Repertorium initiorum}}\plain \f1\lang1033\fs24 , Nr 4672.}

