\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 In den dritten Teil des Traktats eingeschoben:
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Orationes ante et post missam et de corpore Christi}}\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24  (137\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 138\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oratio eiusdem\plain \f1\lang1033\fs24  (i.e. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Thomas de Aquino}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930gi/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ante celebrationem misse}}\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnipotens et misericors deus, ecce accedo ad sacramentum corporis et sanguinis}}\plain \f1\lang1033\fs24  \u8230 \'85 Druck u.a.: Opera omnia, Bd 32, Paris, Viv\u232 \'e8s 1879, S. 821 Nr 6. Weitere Angaben bei {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Theol. lat. oct. 68}}\plain \f1\lang1033\fs24 , 104\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 . (138\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oratio eiusdem dum corpus Christi teneat in manibus\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Adoro te digne latens deitas}}\plain \f1\lang1033\fs24  / \u8230 \'85 {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH}}\plain \f1\lang1033\fs24  50, Nr 389 (in dieser Hs verk\u252 \'fcrzt und mit Umstellung einiger Verse). Weitere Angaben bei {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Theol. lat. oct. 137}}\plain \f1\lang1033\fs24 , 33\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 . (138\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 139\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oratio eiusdem post missam\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Gratias tibi ago pijssime deus, quia me ad offitium sacerdotale elegisti}}\plain \f1\lang1033\fs24  \u8230 \'85 Auch Hs {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Darmstadt, LuHB, Hs 2274}}\plain \f1\lang1033\fs24 , 95\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Kat. Darmstadt 3, S. 39 (Nr 3). Vgl. jeweils {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Dondaine/Shooner}}\plain \f1\lang1033\fs24  Nr 242 (diese Hs). (143\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 144\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Oratio eiusdem\plain \f1\lang1033\fs24  (i.e. {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Albertus Magnus}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930gi/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 de corpore domini Ihesu Christi}}\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnipotens sempiterne deus, fili dei unigenite, qui ex nostro et a nobis et propter nos}}\plain \f1\lang1033\fs24  \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24 omnem sue beatitudinis perfectionem qui cum dulcissime patre\plain \f1\lang1033\fs24  \u8230 \'85 Ed.: Opera omnia. Ed. A. Borgnet, Bd 38, Paris 1898, S. 433\endash 434.}

