\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 68\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 72\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Johannes Belethus}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Summa de ecclesiasticis officiis}}\plain \f1\lang1033\fs24 ], cap. 8\endash 11 u. 15\endash 16, 19\endash 20, 23, 28\endash 29, 51, 69, 96, Exzerpte. (68\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De ieiunio\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sobrii estote vigilate }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 (I Pt 5,8)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 . Videndum, quid sit ieiunium et unde dicitur et de auctoritate sue laudis}}\plain \f1\i\lang1033\fs24  sive commendatione sive origine. Ieiunium est communis omnium membrorum satisfactio\plain \f1\lang1033\fs24  \u8230 \'85\endash  (69\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24 cum brutis animalibus.\plain \f1\lang1033\fs24  (69\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De debitis ad deum\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Res, quas specialiter deo debemus, he sunt: Decime, primicie, vota, sacrificia}}\plain \f1\lang1033\fs24  \u8230 \'85\endash  (72\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24 et erit signum eis, id est crux Christi.\plain \f1\lang1033\fs24  Vgl. Ed.: CCCM 41A, S. 20\endash 29 u. 36\endash 39, 41\endash 43, 48, 55\endash 57, 89f., 129, 128, 172\endash 174.}

