\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 37\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 39\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Auctoritates et notae de sacerdote}}\plain \f1\lang1033\fs24 . (37\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Hugo de Sancto Victore}}\plain \f1\i\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Liber a culpa non est}}\plain \f1\lang1033\fs24  \u8230 \'85 {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 PL}}\plain \f1\lang1033\fs24  176, Sp. 796CD. (38\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Expositio super Mt 22,39. \plain \f1\i\lang1033\fs24 Exposicio illius. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Diliges proximum tuum sicut te ipsum id est quemlibet hominem in vita existentem sicut te ipsum}}\plain \f1\lang1033\fs24  \u8230 \'85 (38\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Nota xvj sunt casus in quibus sacerdos non potest absolvere suum parrochianum\plain \f1\lang1033\fs24 . \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Versus}}\plain \f1\i\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Regula, truncator, incendit, mos}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 sollicitator\plain \f1\lang1033\fs24 .\u8249 \'8b \plain \f1\i\lang1033\fs24 Exposicio versuum. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Regula id est regulare. Truncator id est mutilatorem membrorum. Incendit id est omnes incend}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [i]}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 arios}}\plain \f1\lang1033\fs24  \u8230 \'85 (39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) [\plain \f1\scaps\lang1033\fs24 Versus\plain \f1\lang1033\fs24 ]. 1. am Rand: x\plain \f1\i\lang1033\fs24 ii condiciones confessoris.\plain \f1\lang1033\fs24  Text: {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Confessor dulcis affabilis atque benignus}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\lang1033\fs24\chcbpat17  {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Walther, Initia}}\plain \f1\lang1033\fs24  3135 (mit dieser Hs; jedoch abweichend von PL 207, Sp. 1155). 2. am Rand: \plain \f1\i\lang1033\fs24 Impedimenta confitentis.\plain \f1\lang1033\fs24  Text: {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quatuor impediunt ne crimina confiteantur. Spes, timor atque pudor hiis desperacio maior}}\plain \f1\lang1033\fs24  / \u8230 \'85 Vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Walther, Proverbia}}\plain \f1\lang1033\fs24  23689. {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Item culpa relaxatur numquam nisi sint tibi quinque}}\plain \f1\lang1033\fs24  \u8230 \'85 Vgl. Walther, Initia 3536. Vgl. dieselbe Kombination dieser Verse in Halle, UuLB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Qu. Cod. 85}}\plain \f1\lang1033\fs24 , 156\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , Nr 4\endash 6, Kat. Halle, S. 71. Auf dem Rest der Seite kurze Notae. (39\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) [{\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 De peccatis}}\plain \f1\lang1033\fs24 ]. {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Item quinque dicuntur peccata maxima de sacra scriptura. Primum est excusacio in peccatis et de illis potest allegari}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Sextum superaddit Ieronimus et est odire et fugere sacerdotes suos\plain \f1\lang1033\fs24 .}

