\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 45\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 De filiabus diaboli}}\plain \f1\lang1033\fs24 ]. \plain \f1\i\lang1033\fs24 Nota. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Diabolus habuit octo filias quas maritavit. Prima fuit simonia quam dedit clericis}}\plain \f1\lang1033\fs24  \u8230 \'85 Vgl. Basel, UB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ms. B IX 13}}\plain \f1\lang1033\fs24 , 196\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Kat. Basel 2, S. 210 (Hss u. Lit.). Folgen Zitate aus \plain \f1\i\lang1033\fs24 Isidorus\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Crisostomus}}\plain \f1\lang1033\fs24  und [{\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Ovidius}}\plain \f1\scaps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Fasti}}\plain \f1\lang1033\fs24 ], lib. 1, vs. 419. \endash  Auf den R\u228 \'e4ndern, teils rot gerahmt: [{\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Versus}}\plain \f1\lang1033\fs24 ]. 1. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Walther, Proverbia}}\plain \f1\lang1033\fs24  14453. 2. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O Pater extremum ne nobis dixeris ite / sed nos voce pia fac tunc audire venite}}\plain \f1\i\lang1033\fs24 .\plain \f1\lang1033\fs24  3. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quod hodie fieri poterit non cras tibi fiat}}\plain \f1\lang1033\fs24  \u8230 \'85 Vgl. Walther, Proverbia 25829. 4. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Clerice tu zela crimen nec iniqua vincula}}\plain \f1\lang1033\fs24  / \u8230 \'85 {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Walther, Initia}}\plain \f1\lang1033\fs24  2913 (nach dieser Hs).}

