\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 139\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 144\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Orationes ad Mariam Magdalenam}}\plain \f1\lang1033\fs24 . (139\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 141\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 De sancta Maria Magdalena\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O beatissima Maria Magdalena, gloriosa patrona nostra, moneo te illius doloris, quam habuisti}}\plain \f1\lang1033\fs24  \u8230 \'85 Mehrteiliges Gebet mit dazwischen geschobenen \u8250 \'9b\plain \f1\i\lang1033\fs24 Pater noster\plain \f1\lang1033\fs24 \u8249 \'8b. Schlie\u223 \'dft (141\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Collecta\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CO}}\plain \f1\lang1033\fs24  Nr 3231 (nur Anfang). \u8250 \'9b\plain \f1\i\lang1033\fs24 Collecta\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Beata Maria Magdalena, que pedes domini nostri Ihesu Christi tuis lacrimis rigasti}}\plain \f1\lang1033\fs24  \u8230 \'85 (141\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Collecta\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnipotens sempiterne deus, qui peccatricis mulieris cor pungens ad lacrimas}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 accendisti\plain \f1\lang1033\fs24  \u8230 \'85 \u8250 \'9b\plain \f1\i\lang1033\fs24 Collecta\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Deus, qui beate Marie Magdalene tanto unigeniti tui amoris igne succendisti}}\plain \f1\lang1033\fs24  \u8230 \'85
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (141\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 142\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Alia oracio Marie Magdalene\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH}}\plain \f1\lang1033\fs24  33, Nr 160 (mit Abweichungen in dieser Hs). Die erste Strophe f\u252 \'fcr die Beterin adaptiert: \plain \f1\i\lang1033\fs24 Maria spes venie\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Me famulam tuam respice vultu serena\plain \f1\lang1033\fs24  \u8230 \'85
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (142\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Maria prima sabbati}}\plain \f1\lang1033\fs24  \u8230 \'85 (143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 144\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Gaudia Mariae Magdalenae}}\plain \f1\lang1033\fs24 . (144\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Psalterium Mariae Magdalenae}}\plain \f1\lang1033\fs24 . \u8250 \'9b\plain \f1\i\lang1033\fs24 Psalterium beate Marie Magdalene\plain \f1\lang1033\fs24 \u8249 \'8b. Bricht ab.}

