\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 235\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 237\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Psalterandacht zu Johannes Ev}}\plain \f1\lang1033\fs24 . Einleitung: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Gloria tibi domine Ihesu Christe, qui beatum Iohannem ex nobili tua progenie nasci voluisti}}\plain \f1\lang1033\fs24  \u8230 \'85 \u8250 \'9b\plain \f1\i\lang1033\fs24 Psalmus\plain \f1\lang1033\fs24 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Beatus vir. Gloria tibi domine Ihesu Christe, qui beatum Iohannem nupcias celebrari fecisti}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\lang1033\fs24\chcbpat17  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Rogo te, sancte Iohannes, per eum, qui incarnatus et homo factus humano generi dignatus est}}\plain \f1\lang1033\fs24 \u8230 \'85 Es folgen Gebete im Wechsel mit Psalm 11. 21. 31. 41 (nur Anf\u228 \'e4nge). (236\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24 Versus\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sancte Iohannes, devote te deprecamur}}\plain \f1\lang1033\fs24  \u8230 \'85 \u8250 \'9b\plain \f1\i\lang1033\fs24 Collecta\plain \f1\lang1033\fs24 \u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnipotens et piissime amator hominum, tibi commendamus animas nostras}}\plain \f1\lang1033\fs24  \u8230 \'85 Es folgen Gebete im Wechsel mit Psalm 51. 61. 71. 81 (nur Anf\u228 \'e4nge); bricht im daran anschlie\u223 \'dfenden Gebet ab.}

