\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 S. 533\endash 568 {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Mariengebete}}\plain \f1\lang1033\fs24 , lat. u. dt. Darin u.a.: (S. 534f.) Pium dictamen super Ave Maria. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH}}\plain \f1\lang1033\fs24  30, Nr 126, Str. 1\endash 6. (S. 535f.) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O aller ehrw\u252 \'fcrdigste k\u246 \'f6nigin der barmherzigkeit}}\plain \f1\lang1033\fs24  \u8230 \'85 Vgl. mit weiterer \u220 \'dcberlieferung Hs Freiburg, UB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hs. 45}}\plain \f1\lang1033\fs24 , 91\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 92\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , Kat. Freiburg 1.4 A, S. 24. (S. 549\endash 552) Um ein seliges Ende. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O allers\u252 \'fcsseste fraw Maria, voll aller genaden}}\plain \f1\i\lang1033\fs24  \u8230 \'85, komm mir armen s\u252 \'fcnder zu hilf\plain \f1\lang1033\fs24  \u8230 \'85 Auch Hs Leipzig, UB, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ms 672}}\plain \f1\lang1033\fs24 , 155\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 157\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , Kat. Leipzig, S. 44. (S. 557\endash 560) \plain \f1\i\lang1033\fs24 Modus orandi ad beatam Mariam virginem de septem doloribus.\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Walther, Initia}}\plain \f1\lang1033\fs24  1911. {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Haimerl, Gebetbuchliteratur}}\plain \f1\lang1033\fs24 , S. 125 mit Anm. 745. (S. 560\endash 562) \plain \f1\i\lang1033\fs24 Septem gaudia BMV.\plain \f1\lang1033\fs24  7 Gaude-Gr\u252 \'fc\u223 \'dfe; vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Mone}}\plain \f1\lang1033\fs24  2, Nr 454; {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Meersseman, Der Hymnos Akathistos , 1960}}\plain \f1\lang1033\fs24  2, S. 39f. {\field{\*\fldinst HYPERLINK "hida://bezlit[5].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Chevalier}}\plain \f1\lang1033\fs24  Nr 7017. (S. 563\endash 566) \plain \f1\i\lang1033\fs24 Septem gloriae BMV.\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Frew dich Maria, denn du bist erh\u246 \'f6het uber alle chor der engel}}\plain \f1\lang1033\fs24  \u8230 \'85 Vgl. Haimerl, Gebetbuchliteratur, S. 141 mit Anm. 872. (S. 567f.) Nachtrag, 25. M\u228 \'e4rz 1606: \plain \f1\i\lang1033\fs24 Aveto, mater millies, virgo c\u230 \'e6lestis ave\plain \f1\lang1033\fs24  \u8230 \'85 Druck: Corner, Promptuarium 1619 (wie S. 57), S. 303 (mit kleinen Abweichungen).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Dazwischengeschoben: (S. 539\endash 547) Nachtrag, dt.: \plain \f1\i\lang1033\fs24 Ein sch\u246 \'f6n gebett umb Gedultt zu bitten.\plain \f1\lang1033\fs24  (S. 547) Schlie\u223 \'dft: \plain \f1\i\lang1033\fs24 H\u230 \'e6c descripsi cur ob nimiam confidentiam P. A. fuissem in infimum pistrinum Sylv\u230 \'e6 virid\u230 \'e6 detrusus 8. Augusti 1614 qua fuit festum Petri ad vincula.\plain \f1\lang1033\fs24  Vielleicht Gr\u252 \'fcnwald bei M\u252 \'fcnchen an der Isar.}

